	// (GET /dns/settings/ttl-overrides)
	ListTtlOverrides(c *gin.Context)
	// UpsertTtlOverride 设置或更新域名 TTL 覆盖（reload 生效）
	// (PUT /dns/settings/ttl-overrides)
	UpsertTtlOverride(c *gin.Context)
